export class CertificateMonitor{_peerConnection;_visited=!0;timestamp;id;fingerprint;fingerprintAlgorithm;base64Certificate;issuerCertificateId;attachments;appData;constructor(t,i){this._peerConnection=t,this.id=i.id,this.timestamp=i.timestamp,Object.assign(this,i)}get visited(){const t=this._visited;return this._visited=!1,t}getPeerConnection(){return this._peerConnection}accept(t){this._visited=!0;t.timestamp-this.timestamp<=0||Object.assign(this,t)}createSample(){return{id:this.id,timestamp:this.timestamp,fingerprint:this.fingerprint,fingerprintAlgorithm:this.fingerprintAlgorithm,base64Certificate:this.base64Certificate,issuerCertificateId:this.issuerCertificateId,attachments:this.attachments}}}